2: module domain_ticks #(parameter integer WIDTH=80)(
3:     input wire clk_a, clk_b, reset,
4:     output reg [WIDTH-1:0] count_a,
5:     output reg [WIDTH-1:0] count_b
6: );
7: always @(posedge clk_a or posedge reset) begin
8:     if(reset) count_a <= 0;
9:     else count_a <= count_a + 1;
10: end
11: always @(posedge clk_b or posedge reset) begin
